T["All: Never stand in front of or behind Onyxia (breath/tail).\nPhase 2 from 65%: dodge fireballs, kill whelps at once.\nPhase 3 from 40%: fear - grounding totem and fear ward ready.\nTank: Onyxia with her back to the wall, head away from the raid.\nTank: phase 3 take aggro back at once.\nHealer: tank first, spread out in phase 2.\nDPS: go full only after 3 sunders from the tank.\nDPS: phase 2: whelps before Onyxia."] = "Todos: no os pongáis nunca delante ni detrás de Onyxia (aliento/cola).\nFase 2 desde el 65%: esquivad las bolas de fuego, matad a las crías al instante.\nFase 3 desde el 40%: miedo - Tótem de derribo y Custodia de miedo preparados.\nTanque: Onyxia de espaldas a la pared, cabeza lejos de la banda.\nTanque: en la fase 3 recupera la amenaza al instante.\nSanadores: el tanque tiene prioridad, en la fase 2 separaos.\nDPS: dad caña solo tras 3 ataques por la espalda del tanque.\nDPS: fase 2: crías antes que Onyxia."
T["All: swarm target: run out.\nTank: infernal tank off to the side.\nHealer: remove sleep where possible.\nDPS: ignore infernals, everything on the boss."] = "Todos: objetivo del enjambre: salid fuera.\nTanque: tanque de infernales aparte.\nSanadores: quitad el sueño donde se pueda.\nDPS: ignorad a los infernales, todo al jefe."
T["All: leave Death and Decay at once.\nTank: hold the middle, don't move during frost nova.\nHealer: heal the ice block target fast.\nDPS: ranged spread wide (icebolt chain)."] = "Todos: salid de Muerte y descomposición al instante.\nTanque: mantén el centro, no te muevas con Nova de Escarcha.\nSanadores: curad rápido al objetivo del bloque de hielo.\nDPS: a distancia, bien separados (cadena de Descarga de Escarcha)."
