T["Automatic: every 10 minutes and on logout Oasis stores a snapshot in the saved variables (WTF/Account/<account>/SavedVariables/Oasis.lua). The program Tools/oasis_export.py reads the file, turns it into JSON and can send it to your web page. Addons have no internet access - this is the safe way."] = "Automático: Oasis guarda cada 10 minutos y al cerrar sesión una instantánea en las variables guardadas (WTF/Account/<Cuenta>/SavedVariables/Oasis.lua). El programa Tools/oasis_export.py lee el archivo, lo convierte en JSON y puede enviarlo a vuestra web. Los accesorios no tienen acceso a internet - esta es la vía segura."
