T["The client delivers no skills right now - wait a moment after logging in."] = "El cliente no entrega habilidades ahora mismo - espera un poco tras conectarte."
T["The dungeon compass: which dungeon fits, what drops there for you."] = "La brújula de mazmorras: qué mazmorra encaja y qué cae allí para ti."
T["The enemy was not in front of you. It was behind you. The whole time."] = "El enemigo no estaba delante de ti. Estaba detrás. Todo el tiempo."
