T["The market uses prices from the AH addon Midas. As soon as you or a guild member scans the AH with Midas, this page unlocks."] = "El mercado usa precios del accesorio de subasta Midas. En cuanto tú o alguien de la hermandad escanee la casa de subastas con Midas, esta página se desbloquea."
T["Play-time tracking is off. Turn it on and Oasis learns a little more every evening."] = "El registro de horas de juego está desactivado. Actívalo y Oasis aprenderá con cada tarde."
T["The Oasis rank is Oasis's guild rank - it rises by playing together, helping, crafting, events and badges."] = "El rango de Oasis es el rango de hermandad de Oasis - sube jugando juntos, ayudando, con artesanía, citas e insignias."
T["This person's online sound is muted for you."] = "Tienes desactivado el sonido de conexión de esta persona."
