T["The chat input was touched by Oasis (e.g. 'Whisper' button), then /target was typed."] = "Oasis había tocado la entrada del chat (p. ej. botón 'Susurrar') y después se escribió /target."
T["The chat input was touched by Oasis (e.g. 'Whisper' button), then a /cast command was typed there."] = "Oasis había tocado la entrada del chat (p. ej. botón 'Susurrar') y después se escribió allí un comando /cast."
T["The chat input was touched by Oasis, then /focus was typed."] = "Oasis había tocado la entrada del chat y después se escribió /focus."
T["The chat input was touched by Oasis, then a spell command was typed."] = "Oasis había tocado la entrada del chat y después se escribió un comando de hechizo."
T["Dungeon maps have no coordinates. Click here, then on the spot where you stand. Done at two distant spots, Oasis shows you and your group on the map - for the whole guild."] = "Los mapas de mazmorra no tienen coordenadas. Haz clic aquí y luego en el punto del mapa donde estás ahora. Hecho en dos puntos muy alejados, Oasis te muestra a ti y a tu grupo en el mapa - para toda la hermandad."
T["The guild will be notified"] = "La hermandad recibe el aviso"
T["The guild can see whom you react to. Default: off"] = "La hermandad ve a quién respondes. Por defecto: desactivado"
T["The guild sees your fire on the map for %d minutes."] = "La hermandad ve tu fuego %d minutos en el mapa."
T["The guild sees your achievements in the chronicle"] = "La hermandad ve en la crónica lo que has logrado"
T["The guild isn't looking for anything from this dungeon."] = "La hermandad no busca nada de esta mazmorra ahora mismo."
T["Your guild doesn't award loot points yet - your values appear once the raid leaders start a raid."] = "La hermandad aún no reparte puntos de botín - tus valores aparecerán cuando la dirección de banda inicie una banda."
T["The guild bank hasn't been read yet"] = "El banco de hermandad aún no se ha leído"
T["The guild leadership names raid leaders and assistants under Crown > Modules > Raids & Loot (by name or from a guild rank). In a running raid, the raid leader and assistants count too."] = "La dirección de hermandad nombra líderes y asistentes de banda en Corona > Módulos > Bandas y botín (nombres o desde un rango de hermandad). En una banda en curso cuentan también el líder y los asistentes de banda."
T["The guild leadership names raid leaders under Crown > Modules > Raids & Loot. In a running raid, the raid leader and assistants count too."] = "La dirección de hermandad nombra líderes de banda en Corona > Módulos > Bandas y botín. En una banda en curso cuentan también el líder y los asistentes de banda."
T["The guild leadership names raid leaders under Crown > Modules > Raids & Loot. In a running raid, the raid leader counts too."] = "La dirección de hermandad nombra líderes de banda en Corona > Módulos > Bandas y botín. En una banda en curso cuenta también el líder de banda."
T["The guild leadership only allows group searches from a higher rank."] = "La dirección de hermandad solo permite búsquedas de grupo desde un rango superior."
T["The guild leadership only allows polls from a higher rank."] = "La dirección de hermandad solo permite encuestas desde un rango superior."
T["The guild leadership has disabled the partner search."] = "La dirección de hermandad ha desactivado la búsqueda de compañeros."
T["The guild leadership has disabled open invites - challenge someone directly."] = "La dirección de hermandad ha desactivado las invitaciones abiertas - reta a alguien directamente."
T["The guild leadership sets which ranks may do this under Crown > Modules."] = "La dirección de hermandad decide en Corona > Módulos qué rangos pueden hacerlo."
T["WoW's guild finder helps - neutral, no ads."] = "El buscador de hermandades de WoW ayuda a encontrar - neutral, sin publicidad."
T["Only the guild master sets the limit. Rank 1 = guild master."] = "El límite solo lo fija el maestro de la hermandad. Rango 1 = maestro de la hermandad."
T["The buttons put the command into the chat line - it only runs when you press Enter."] = "Los botones escriben el comando en la línea de chat - solo se ejecuta al pulsar Intro."
T["The shortcuts are also in WoW's key bindings under AddOns > Oasis. Esc closes the Oasis window (not in combat - there Esc belongs to the game)."] = "Los atajos también están en las asignaciones de teclas de WoW, en AddOns > Oasis. Esc cierra la ventana de Oasis (en combate no - ahí Esc es del juego)."
T["The shortcuts are also in WoW's key bindings under AddOns > Oasis. Esc closes the Oasis window as long as you last clicked into it."] = "Los atajos también están en las asignaciones de teclas de WoW, en AddOns > Oasis. Esc cierra la ventana de Oasis mientras hayas hecho clic en ella lo último."
T["The bar rolls up out of view; move the mouse to the top edge and it comes down (only when docked at the top)"] = "La barra se repliega hacia arriba; lleva el ratón al borde superior y baja (solo si está acoplada arriba)"
