T["Who sends data that others reject (no permission, forged author, made-up entries). An unmodified Oasis practically never does this - a hint, not proof."] = "Quien envía datos que los demás rechazan (sin permisos, autor falsificado, entradas inventadas). Un Oasis sin modificar casi nunca hace esto - es un indicio, no una prueba."
