T["Whoever shows up often and has received little gets first pick on 'Need'. Part of the points decays every week."] = "Quien viene a menudo y ha recibido poco tiene prioridad en 'Necesidad'. Cada semana caduca una parte de los puntos."
T["Anyone who signs up with a fitting role is invited to your group right away."] = "Quien se apunte con un rol adecuado es invitado a tu grupo al instante."
