T["Who deals, heals and takes the most?"] = "¿Quién hace más daño, cura más y recibe más?"
T["The guild master decides who belongs to the leadership under Crown > Guild."] = "Quién pertenece a la dirección de la hermandad lo decide el maestro de hermandad en Corona > Hermandad."
T["Stats"] = "Estadísticas"
T["stats do nothing for your role"] = "Las estadísticas no aportan nada a tu rol"
T["stats for info only"] = "Estadísticas solo informativas"
T["Stats, yearbook, daily goal, records and adventures of your character."] = "Estadísticas, anuario, objetivo diario, récords y aventuras de tu personaje."
T["Stats: +healing, intellect, spirit, mp5;Weapon: staff or one-hander + off-hand with healing;Healing: Rejuvenation and Regrowth ahead, Healing Touch for big hits;Tip: Innervate for mana, Rebirth for fallen healers"] = "Estadísticas: +sanación, intelecto, espíritu, regen. de maná;Arma: bastón o arma de una mano + mano izquierda con sanación;Sanar: Rejuvenecimiento y Recrecimiento por adelantado, Toque de sanación para golpes fuertes;Consejo: Estimular para maná, Renacer para sanadores caídos"
T["Stats: +healing, intellect, spell crit (Illumination refunds mana), mp5;Weapon: one-hander + off-hand/shield with healing;Healing: Flash of Light for small damage, Holy Light (low rank) for big hits;Tip: hand out blessings, Divine Protection when you pull aggro"] = "Estadísticas: +sanación, intelecto, crítico con hechizos (Iluminación devuelve maná), regen. de maná;Arma: arma de una mano + mano izquierda/escudo con sanación;Sanar: Destello de Luz para daño pequeño, Luz Sagrada (rango bajo) para golpes fuertes;Consejo: reparte bendiciones, Protección divina si atraes amenaza"
T["Stats: +healing, mp5, intellect - spirit does little;Weapon: one-hander + shield with healing;Healing: Chain Heal for groups, Healing Wave (low rank) for the tank;Tip: drop Mana Spring Totem, Earth Shield on the tank"] = "Estadísticas: +sanación, regen. de maná (MP5), intelecto - el espíritu aporta poco;Arma: arma de una mano + escudo con sanación;Sanar: Sanación en cadena para grupos, Ola de sanación (rango bajo) para el tanque;Consejo: pon el Tótem Fuente de maná, Escudo de tierra en el tanque"
T["Stats: +healing, spirit (Meditation: regen while casting), intellect, mp5;Weapon: staff or one-hander + off-hand with healing, wand;Healing: Renew and Power Word: Shield ahead, Greater Heal (low rank) for the tank;Tip: Prayer of Healing for the group, Fade on aggro"] = "Estadísticas: +sanación, espíritu (Meditación: regeneración también al lanzar), intelecto, regen. de maná;Arma: bastón o arma de una mano + mano izquierda con sanación, varita;Sanar: Renovar y Palabra de poder: escudo por adelantado, Sanación superior (rango bajo) para el tanque;Consejo: Rezo de sanación para el grupo, Desvanecerse si tienes amenaza"
T["Stats: armor (bear form multiplies it), stamina, agility (dodge + armor);Weapon: damage doesn't matter - only the stats (staff/polearm with stamina);Rotation: Maul, Swipe for packs, Demoralizing Roar;Tip: strength for more threat, Enrage to start"] = "Estadísticas: armadura (la forma de oso la multiplica), aguante, agilidad (esquivar + armadura);Arma: el daño da igual - solo cuentan las estadísticas (bastón/arma de asta con aguante);Rotación: Magullar, Flagelo para grupos, Rugido desmoralizador;Consejo: fuerza para más amenaza, Enfurecer al empezar"
T["Stats: strength (1 point = 2 AP), agility (AP + crit), crit, hit up to +9 %;Weapon: damage doesn't matter - only the stats;Rotation: Claw/Shred for combo points, then Ferocious Bite;Tip: powershift (recast form) for energy, open from stealth"] = "Estadísticas: fuerza (1 punto = 2 PA), agilidad (PA + crítico), crítico, golpe hasta +9 %;Arma: el daño da igual - solo cuentan las estadísticas;Rotación: Zarpa/Triturar para puntos de combo, luego Mordedura feroz;Consejo: powershift (volver a la forma) para energía, abrir desde sigilo"
T["Stats: strength (1 point = 2 AP), crit (procs Flurry = faster swings), hit up to +9 %;Weapon: slow two-hander - Windfury procs per swing, so slower = more damage;Rotation: Windfury Weapon, Stormstrike, Earth Shock;Tip: Strength of Earth and Windfury Totem for the group"] = "Estadísticas: fuerza (1 punto = 2 PA), crítico (activa Ráfaga = golpes más rápidos), golpe hasta +9 %;Arma: arma de dos manos lenta - Viento Furioso se activa por golpe, así que más lenta = más daño;Rotación: Arma Viento Furioso, Golpe de tormenta, Choque de tierra;Consejo: Tótem Fuerza de la tierra y Tótem Viento Furioso para el grupo"
T["Stats: strength (1 point = 2 AP), crit, hit up to +9 %;Weapon: slow two-hander - seals and Judgement scale per swing;Rotation: Seal of Righteousness/Command, Judgement, reapply seal;Tip: Consecration only with enough mana, Blessing of Might on yourself"] = "Estadísticas: fuerza (1 punto = 2 PA), crítico, golpe hasta +9 %;Arma: arma de dos manos lenta - sellos y Sentencia escalan por golpe;Rotación: Sello de rectitud/de orden, Sentencia, volver a poner el sello;Consejo: Consagración solo con maná suficiente, Bendición de poderío para ti"
T["Stats: hit up to +9 %, agility (1 AP, ~29 = 1 % crit), AP, crit;Weapon: Combat = fast off-hand, slow main hand (Sinister Strike); daggers for Backstab;Rotation: build combo points, keep Slice and Dice up, then Eviscerate;Tip: dual wielding misses white hits more often - hit matters most"] = "Estadísticas: golpe hasta +9 %, agilidad (1 PA, aprox. 29 = 1 % de crítico), PA, crítico;Arma: Combate = mano izquierda rápida, mano derecha lenta (Golpe siniestro); dagas para Puñalada;Rotación: acumula puntos de combo, mantén Hacer picadillo, luego Eviscerar;Consejo: con dos armas los golpes normales fallan más - el golpe es lo más importante"
T["Stats: hit up to +9 %, agility (2 ranged AP, ~53 = 1 % crit), AP, intellect;Weapon: slow ranged weapon (big damage per shot), melee weapon for stats;Rotation: Hunter's Mark, Auto Shot, Aimed Shot/Multi-Shot in between;Tip: feed your pet and keep it happy, Freezing Trap (square) for control"] = "Estadísticas: golpe hasta +9 %, agilidad (2 PA a distancia, aprox. 53 = 1 % de crítico), PA, intelecto;Arma: arma a distancia lenta (mucho daño por disparo), arma cuerpo a cuerpo por las estadísticas;Rotación: Marca del cazador, Disparo automático, Disparo apuntado/Disparo múltiple entre medias;Consejo: alimenta a tu mascota y mantenla contenta, Trampa congelante (cuadrado) para control"
T["Stats: hit up to +9 %, strength (1 point = 2 AP), crit (~20 agility = 1 %);Weapon: slow two-hander (Mortal Strike, Heroic Strike scale per swing);Rotation: build rage, Mortal Strike / Bloodthirst, Whirlwind, spare rage into Heroic Strike;Tip: Battle Shout before the pull, Execute below 20 % health"] = "Estadísticas: golpe hasta +9 %, fuerza (1 punto = 2 PA), crítico (aprox. 20 agilidad = 1 %);Arma: arma de dos manos lenta (Golpe mortal y Golpe heroico escalan por golpe);Rotación: genera ira, Golpe mortal / Sed de sangre, Torbellino, ira sobrante en Golpe heroico;Consejo: Grito de batalla antes del combate, Ejecutar por debajo del 20 % de salud"
T["Stats: defense (440 = crit immune vs bosses at 60), stamina, armor, block;Weapon: one-hander + shield, fast weapon = more rage;Rotation: Shield Slam/Revenge, Sunder Armor on the target, Heroic Strike with high rage;Tip: hit helps so Taunt and abilities don't miss"] = "Estadísticas: defensa (440 = inmune a críticos de jefes a nivel 60), aguante, armadura, bloqueo;Arma: arma de una mano + escudo, arma rápida = más ira;Rotación: Embate con escudo/Revancha, Hender armadura en el objetivo, Golpe heroico con mucha ira;Consejo: el golpe ayuda a que Provocar y las habilidades no fallen"
T["Stats: defense, stamina, armor, then spell damage for more threat;Weapon: one-hander (ideally spell damage) + shield;Rotation: Righteous Fury on, Consecration for packs, keep Holy Shield up;Tip: mana is tight - use Seal of Wisdom or some intellect"] = "Estadísticas: defensa, aguante, armadura, luego daño con hechizos para más amenaza;Arma: arma de una mano (mejor con daño con hechizos) + escudo;Rotación: Furia justa activa, Consagración para grupos, mantén Escudo sagrado;Consejo: el maná escasea - usa Sello de sabiduría o algo de intelecto"
T["Stats: spell damage, spell crit (Elemental Focus saves mana), intellect, mp5;Weapon: one-hander + shield/off-hand with spell damage;Rotation: spam Lightning Bolt, Chain Lightning on packs, Flame Shock;Tip: spell hit up to +16 % in raids, Mana Spring Totem against oom"] = "Estadísticas: daño con hechizos, crítico con hechizos (Foco elemental ahorra maná), intelecto, regen. de maná;Arma: arma de una mano + escudo/mano izquierda con daño con hechizos;Rotación: Descarga de relámpagos sin parar, Cadena de relámpagos para grupos, Choque de llamas;Consejo: golpe con hechizos hasta +16 % en banda, Tótem Fuente de maná contra quedarte sin maná"
T["Stats: spell damage, spell crit, intellect, spell hit up to +16 % in raids;Weapon: staff or one-hander + off-hand with spell damage;Rotation: Moonfire + Insect Swarm, then Wrath or Starfire;Tip: Innervate yourself when mana runs low"] = "Estadísticas: daño con hechizos, crítico con hechizos, intelecto, golpe con hechizos hasta +16 % en banda;Arma: bastón o arma de una mano + mano izquierda con daño con hechizos;Rotación: Fuego lunar + Enjambre de insectos, luego Cólera o Fuego estelar;Consejo: Estimular sobre ti cuando escasee el maná"
T["Stats: spell damage, spell hit up to +16 % (raid), stamina, intellect;Weapon: staff or dagger + off-hand with spell damage, wand for leftover mana;Rotation: Corruption + curse, then Shadow Bolt; Life Tap instead of drinking;Tip: stamina pays off twice (Life Tap, Voidwalker/Soul Link)"] = "Estadísticas: daño con hechizos, golpe con hechizos hasta +16 % (banda), aguante, intelecto;Arma: bastón o daga + mano izquierda con daño con hechizos, varita para el maná restante;Rotación: Corrupción + maldición, luego Descarga de las Sombras; Transfusión de vida en vez de beber;Consejo: el aguante compensa doble (Transfusión de vida, abisario/Vínculo de alma)"
T["Stats: spell damage, spell hit up to +16 % (raid), spirit for mana;Weapon: staff or one-hander + off-hand with spell damage;Rotation: Shadow Word: Pain, Mind Blast, Mind Flay;Tip: stay in Shadowform, Vampiric Embrace heals the group"] = "Estadísticas: daño con hechizos, golpe con hechizos hasta +16 % (banda), espíritu para maná;Arma: bastón o arma de una mano + mano izquierda con daño con hechizos;Rotación: Palabra de las Sombras: dolor, Explosión mental, Tortura mental;Consejo: Forma de las Sombras siempre activa, Abrazo vampírico cura al grupo"
T["Stats: spell damage, then spell hit up to +16 % (raid bosses), intellect, spell crit;Weapon: staff with spell damage, plus a wand for leftover mana;Rotation: spam Frostbolt or Fireball, Evocation when out of mana;Leveling: intellect and spirit = less downtime, sheep (moon) in groups"] = "Estadísticas: daño con hechizos, luego golpe con hechizos hasta +16 % (jefes de banda), intelecto, crítico con hechizos;Arma: bastón con daño con hechizos, más una varita para el maná restante;Rotación: Descarga de Escarcha o Bola de Fuego sin parar, Evocación sin maná;Subir de nivel: intelecto y espíritu = menos pausas, en grupo oveja (luna)"
