T["Shows better / worse / can't equip with effect (DPS, health, armor) and a stats table. Blizzard's comparison then only appears with Shift. If nesUI with its own comparison is loaded, Oasis shows nothing (otherwise doubled) - turn it off there with /nes vergleich."] = "Muestra Mejor / Peor / No equipable con su efecto (DPS, salud, armadura) y tabla de estadísticas. La comparación de Blizzard solo aparece con Mayús. Si nesUI está cargado con su propia comparación, Oasis no muestra nada (si no, saldría doble) - desactívala allí con /nes vergleich."
