T["1.  Keep the combat log on (Settings > Areas > Combat board, on by default).\n2.  After playing, double-click ImportCrits.bat in the Oasis folder.\n3.  /reload in game - your highest crit shows here and is shared with the guild."] = "1.  Deja activado el registro de combate (Ajustes > Secciones > Clasificación de combate, activado por defecto).\n2.  Después de jugar, haz doble clic en ImportCrits.bat en la carpeta de Oasis.\n3.  /reload en el juego: tu crítico más alto aparece aquí y se comparte con la hermandad."
