T["Active members below the officer ranks appear in the 'Promotion' list after this many days in the same rank. 0 = off."] = "Los miembros activos por debajo de los rangos de oficial aparecen en la lista 'Ascenso' tras tantos días en el mismo rango. 0 = desactivado."
T["Current zone first"] = "Zona actual primero"
T["All areas, grouped by topic: guild, playing together, raid, trade, fun. Click a heading to collapse its group."] = "Todas las secciones, agrupadas por tema: hermandad, jugar juntos, banda, comercio, diversión. Haz clic en un título para plegar su grupo."
T["Expand all zones"] = "Desplegar todas las zonas"
T["Collapse all zones"] = "Plegar todas las zonas"
T["All members with rank, level and Oasis version. Right-click a row: change rank."] = "Todos los miembros con rango, nivel y versión de Oasis. Clic derecho en una fila: cambiar rango."
T["All fonts under the SIL Open Font License 1.1"] = "Todas las fuentes bajo la SIL Open Font License 1.1"
T["All: Burning Adrenaline: run out of the raid AT ONCE (you are about to die).\nAll: Full resources at the start - use everything.\nTank: Set a tank order (Adrenaline on the tank).\nDD: Not in front of or behind the dragon."] = "All: Adrenalina ardiente: salir de la banda YA (vas a morir).\nAll: Recursos llenos al empezar: usarlo todo.\nTank: Fijar un orden de tanques (Adrenalina en el tanque).\nDD: Ni delante ni detrás del dragón."
T["All: Do not let the 8 Firesworn die near the raid (explosion).\nTank: Each add tank pulls their Firesworn away, warlocks banish.\nHealer: Dispel, keep an eye on the add tanks.\nDD: Garr first, adds only when called."] = "All: No dejar morir a los 8 Firesworn cerca de la banda (explosión).\nTank: Cada tanque de adds aleja a su Firesworn, los brujos destierran.\nHealer: Disipar, vigilar a los tanques de adds.\nDD: Garr primero, adds solo cuando se indique."
T["All: Tank the two Core Ragers away from the boss, do not kill them.\nTank: Swap the Golemagg tank when Magma Splash stacks too high.\nDD: Only on Golemagg."] = "All: Tanquear a los dos Core Ragers lejos del jefe, no matarlos.\nTank: Cambiar de tanque en Golemagg si Magma Splash acumula demasiado.\nDD: Solo a Golemagg."
T["All: The 4 priests first, they heal each other.\nTank: Keep Sulfuron and the priests apart.\nDD: Interrupt! Stop the priests' Dark Mending."] = "All: Primero los 4 sacerdotes, se curan entre sí.\nTank: Sulfuron y los sacerdotes separados.\nDD: ¡Interrumpir! Cortar Dark Mending de los sacerdotes."
T["All: Fire protection! Wrath of Ragnaros knocks melee back - then get back in.\nAll: Sons phase (after 3 min or when he submerges): kill all Sons of Flame.\nTank: Second tank ready when the first is knocked away.\nHealer: Spread out, ranged not too close (Lava Burst).\nDD: Melee: keep mana under control, ranged keep your distance."] = "All: ¡Protección contra el fuego! Ira de Ragnaros lanza lejos al cuerpo a cuerpo: luego volver.\nAll: Fase de los hijos (tras 3 min o cuando se sumerge): matar a todos los Hijos de la Llama.\nTank: Segundo tanque listo cuando el primero salga despedido.\nHealer: Repartidos, los de distancia no demasiado cerca (Lava Burst).\nDD: Cuerpo a cuerpo: controlar el maná; distancia: mantener la distancia."
T["All: Flame Buffet stacks - ranged behind pillars to let it drop.\nTank: Two tanks behind pillars, Wing Buffet knocks back.\nDD: Onyxia Scale Cloak required."] = "All: Flame Buffet se acumula: los de distancia tras los pilares para que se quite.\nTank: Dos tanques tras los pilares, Wing Buffet empuja hacia atrás.\nDD: Capa de escamas de Onyxia obligatoria."
T["All: Remove Gehennas' Curse (reduced healing) at once.\nAll: Get out of the Rain of Fire.\nTank: Tank the two Flamewakers apart.\nDD: Flamewakers first, then Gehennas."] = "All: Quitar Maldición de Gehennas (menos sanación) al instante.\nAll: Salir de la Lluvia de Fuego.\nTank: Tanquear a los dos Flamewakers por separado.\nDD: Flamewakers primero, luego Gehennas."
T["All: Remove Lucifron's Curse and Impending Doom at once (mages/druids, priests/paladins).\nTank: Tank the two guards apart - mind control!\nHealer: Spread out, dispel mind-controlled players.\nDD: Guards first, then Lucifron."] = "All: Quitar Maldición de Lucifron e Impending Doom al instante (magos/druidas, sacerdotes/paladines).\nTank: Tanquear a los dos guardias por separado: ¡control mental!\nHealer: Repartidos, disipar a los jugadores con control mental.\nDD: Primero los guardias, luego Lucifron."
T["All: Living Bomb: run out of the raid AT ONCE!\nAll: Inferno - away from the boss, dispel Ignite Mana.\nTank: Hold the middle, step out briefly on Inferno.\nDD: Melee back off on Inferno."] = "All: Bomba viviente: ¡salir de la banda YA!\nAll: Inferno: lejos del jefe, disipar Ignite Mana.\nTank: Mantener el centro, salir un momento con Inferno.\nDD: Cuerpo a cuerpo, atrás con Inferno."
T["All: Watch the guards' magic reflection/damage shield - stop damage then.\nTank: One guard per tank, mages sheep the elite guards.\nDD: Healer guards (Flamewaker Healer) first."] = "All: Ojo al reflejo de magia/escudo de daño de los guardias: entonces parar el daño.\nTank: Un guardia por tanque, los magos polimorfan a los guardias de élite.\nDD: Guardias sanadores (Flamewaker Healer) primero."
T["All: Never stand in front of or behind Onyxia (breath and tail sweep).\nAll: Phase 2 (65%): dodge fireballs, stay out of the cave entrances.\nAll: Phase 3 (40%): fear - Fear Ward/Tremor Totem ready, avoid the lava cracks.\nTank: Onyxia sideways at the wall, head away from the raid.\nTank: Phase 2: pick up the whelps. Phase 3: get aggro back at once.\nHealer: Tank has priority, spread out in phase 2.\nDD: Wait for 3 attacks of the tank. Phase 2: whelps first."] = "All: Nunca delante ni detrás de Onyxia (aliento y coletazo).\nAll: Fase 2 (65%): esquivar las bolas de fuego, no entrar en las cuevas.\nAll: Fase 3 (40%): miedo: Custodia de miedo/Tótem de tremor listos, evitar las grietas de lava.\nTank: Onyxia de lado contra la pared, cabeza lejos de la banda.\nTank: Fase 2: recoger las crías. Fase 3: recuperar el agro al instante.\nHealer: El tanque tiene prioridad, repartidos en fase 2.\nDD: Esperar 3 ataques del tanque. Fase 2: crías primero."
T["All: Panic - Fear Ward/Tremor Totem, hunters: Tranquilizing Shot on Frenzy.\nAll: Get out of the lava fire on the ground.\nTank: Magmadar with his back to the raid.\nDD: Ranged spread out at the back."] = "All: Pánico: Custodia de miedo/Tótem de tremor; cazadores: Disparo tranquilizante en Frenesí.\nAll: Salir del fuego de lava del suelo.\nTank: Magmadar de espaldas a la banda.\nDD: Los de distancia repartidos atrás."
T["All: Phase 1: dragonkin from both sides, watch the class calls.\nAll: Phase 3 (20%): the skeletons rise again - kill them again.\nTank: Nefarian at the wall, fear - Fear Ward.\nHealer: Class call for priests: healing hurts - be careful.\nDD: Hunters/warriors: watch the class calls (weapons gone, stance)."] = "All: Fase 1: dragonantes por ambos lados, ojo a las llamadas de clase.\nAll: Fase 3 (20%): los esqueletos se levantan de nuevo: matarlos otra vez.\nTank: Nefarian contra la pared, miedo: Custodia de miedo.\nHealer: Llamada de clase para sacerdotes: la sanación hace daño, cuidado.\nDD: Cazadores/guerreros: ojo a las llamadas de clase (sin armas, actitud)."
T["All: Phase 1: destroy the eggs (mind control via the orb), pick up the adds.\nAll: After all eggs: boss in the room - Fire Nova.\nTank: Gather the adds at the stairs.\nDD: Mages and dragonkin first."] = "All: Fase 1: destruir los huevos (control mental con el orbe), recoger los adds.\nAll: Tras todos los huevos: jefe en la sala: Nova de Fuego.\nTank: Juntar los adds en las escaleras.\nDD: Magos y dragonantes primero."
T["All: Frenzy - hunters: Tranquilizing Shot.\nTank: Two tanks, watch Wing Buffet.\nDD: Onyxia Scale Cloak required."] = "All: Frenesí: cazadores, Disparo tranquilizante.\nTank: Dos tanques, ojo a Wing Buffet.\nDD: Capa de escamas de Onyxia obligatoria."
T["All: Shadow of Ebonroc heals the boss - the tank with the debuff swaps.\nTank: Two tanks swap on Shadow.\nDD: Onyxia Scale Cloak required."] = "All: Sombra de Ebanorroca cura al jefe: el tanque con el perjuicio cambia.\nTank: Dos tanques cambian con Sombra.\nDD: Capa de escamas de Onyxia obligatoria."
T["All: Knockback - stand against the wall.\nTank: Two tanks, aggro is split by Knock Away.\nDD: Mortal Strike on the tank: healers be prepared."] = "All: Empuje: colocarse contra la pared.\nTank: Dos tanques, Knock Away reparte el agro.\nDD: Golpe mortal en el tanque: sanadores, atentos."
T["All: He teleports - whoever has aggro, do not run away.\nAll: Remove Shazzrah's Curse, Arcane Explosion: melee keep your distance.\nTank: Get back on him right after every blink.\nHealer: Dispel (Deaden Magic)."] = "All: Se teletransporta: quien tenga el agro, que no huya.\nAll: Quitar Maldición de Shazzrah; Explosión Arcana: cuerpo a cuerpo a distancia.\nTank: Volver a él justo tras cada traslación.\nHealer: Disipar (Deaden Magic)."
T["All: Two of the five breath types per week - avoid the breath behind the corner.\nAll: Hourglass Sand for the Bronze affliction.\nTank: Tank at the gate, raid behind the corner.\nDD: Tranquilizing Shot on Frenzy."] = "All: Dos de los cinco tipos de aliento por semana: el aliento se evita tras la esquina.\nAll: Hourglass Sand para la aflicción de bronce.\nTank: Tanquear en la puerta, banda tras la esquina.\nDD: Disparo tranquilizante en Frenesí."
T["Hold Alt: all stats and scoring details. Shift: Blizzard comparison."] = "Mantén Alt: todos los valores y la puntuación. Mayús: comparación de Blizzard."
T["Release Alt: compact view. Shift: Blizzard comparison."] = "Suelta Alt: vista compacta. Mayús: comparación de Blizzard."
